sealed class ErrorLocation {
 public string Raw; public int Line,Column;
 public static List<ErrorLocation> Parse(string raw){var result=new List<ErrorLocation>();foreach(string line in (raw??"").Replace("\r","").Split('\n')){var m=Regex.Match(line,@"(?:^|[\\/\s])?(?:answer|trial)\.c:(\d+)(?::(\d+))?\s*:");int row,col=1;if(m.Success&&int.TryParse(m.Groups[1].Value,out row)&&row>0){if(m.Groups[2].Success&&!int.TryParse(m.Groups[2].Value,out col))continue;result.Add(new ErrorLocation{Raw=line,Line=row,Column=Math.Max(1,col)});}}return result;}
 public static bool Jump(CodeEditor editor,int line,int column){if(editor==null||line<1||line>editor.Input.Document.LineCount)return false;var docLine=editor.Input.Document.GetLineByNumber(line);int col=Math.Max(1,Math.Min(column,docLine.Length+1));editor.Input.Select(docLine.Offset+col-1,0);editor.Input.ScrollTo(line,col);editor.Input.Focus();return true;}
}

static class PracticeTools {
 public static void CloseThen(Window window,Action action){var owner=window.Owner;window.Closed+=(s,e)=>{if(owner!=null)owner.Dispatcher.BeginInvoke((Action)(()=>{owner.Activate();action();}));else action();};window.Close();}
 public static string CaseText(CaseResult c){return L.T("输入\n")+c.Test.Input+L.T("\n\n预期输出\n")+c.Test.Expected+L.T("\n\n实际输出\n")+(c.Run.Output==""?L.T("（无输出）"):c.Run.Output)+L.T("\n\n诊断\n")+L.Diagnosis(c.Diagnosis)+L.T("\n\n耗时 ")+c.Run.Millis.ToString("0.0")+" ms · CPU "+c.Run.CpuMillis.ToString("0.0")+" ms · Exit "+c.Run.ExitCode+"\n\n[stderr]\n"+(c.Run.Error==""?L.T("（无）"):c.Run.Error);}
 public static string Report(Evaluation ev){var b=new StringBuilder();b.AppendLine(L.T(Branding.Title)+" · "+L.T("评测报告")).AppendLine(L.T("题目：")+ev.ProblemId+" "+L.T(ev.Title)).AppendLine(L.T("时间：")+ev.Time).AppendLine(L.T("随机种子：")+ev.Seed).AppendLine(L.T("得分：")+ev.Score+" / 100");b.AppendLine(L.T("随机正确性：")+ev.NormalScore.ToString("0.0")+" / 60 · "+L.T("边界正确性：")+ev.EdgeScore.ToString("0.0")+" / 20 · "+L.T("运行质量：")+ev.QualityScore.ToString("0.0")+" / 10 · "+L.T("简洁度：")+(ev.LineScore+ev.SizeScore).ToString("0.0")+" / 10");b.AppendLine(L.T(CodeMetrics.Describe(ev))).AppendLine(L.T(Theme.Rules)).AppendLine(L.T(Branding.Attribution));b.AppendLine(L.T("编译信息：")).AppendLine(L.T(Theme.CompileAdvice(ev.Compiler,ev.Compiled)));for(int i=0;i<ev.Cases.Count;i++)b.AppendLine("\n"+L.T("用例 ")+(i+1)+" / "+L.T(ev.Cases[i].Test.Edge?"边界":"随机")+" / "+L.T(ev.Cases[i].Passed?"通过":"失败")).AppendLine(CaseText(ev.Cases[i]));b.AppendLine(L.T("\n提交代码：")).Append(ev.Code);return b.ToString();}
 public static void WireDiagnostics(TextBox box,Action<int,int> jump){box.PreviewMouseLeftButtonUp+=(s,e)=>{int index=box.GetCharacterIndexFromPoint(e.GetPosition(box),true);if(index<0)return;int row=box.GetLineIndexFromCharacterIndex(index);if(row<0)return;var item=ErrorLocation.Parse(box.GetLineText(row)).FirstOrDefault();if(item!=null){e.Handled=true;jump(item.Line,item.Column);}};}
 public static Button Icon(string label,string geometry,Action action,bool dark=false){var b=dark?Dark.Button(""):Theme.Button("");b.Width=36;b.Height=32;b.MinHeight=32;b.Padding=new Thickness(6,4,6,4);b.Margin=new Thickness(3,0,3,0);var path=new System.Windows.Shapes.Path{Data=Geometry.Parse(geometry),Width=18,Height=18,Stretch=Stretch.Uniform,StrokeThickness=1.45,StrokeStartLineCap=PenLineCap.Round,StrokeEndLineCap=PenLineCap.Round,StrokeLineJoin=PenLineJoin.Round};path.SetBinding(System.Windows.Shapes.Shape.StrokeProperty,new System.Windows.Data.Binding("Foreground"){Source=b});b.Content=path;b.ToolTip=label;b.Tag="tool:"+label;System.Windows.Automation.AutomationProperties.SetName(b,label);ToolTipService.SetInitialShowDelay(b,300);b.Click+=(s,e)=>action();return b;}
 public const string Book="M 3 2 L 16 2 16 18 3 18 Z M 6 6 L 13 6 M 6 10 L 13 10 M 6 14 L 10 14";
 public const string Compare="M 2 3 L 8 3 8 17 2 17 Z M 12 3 L 18 3 18 17 12 17 Z M 9 8 L 11 10 9 12";
 public const string Terminal="M 2 3 L 18 3 18 17 2 17 Z M 5 7 L 8 10 5 13 M 10 13 L 15 13";
 public const string Target="M 10 2 A 8 8 0 1 0 10 18 A 8 8 0 1 0 10 2 M 10 6 L 10 14 M 6 10 L 14 10";
 public static void Diagnostics(Window owner,string raw,Action<int,int> jump,bool dark=false){var locations=ErrorLocation.Parse(raw);if(locations.Count==0){AppDialog.Show(owner,"没有可跳转的源码行号。运行错误通常没有精确行号，请结合失败用例检查。","错误定位");return;}var w=new Window{Title="错误定位",Owner=owner,Width=760,Height=520,MinWidth=520,MinHeight=350,WindowStartupLocation=WindowStartupLocation.CenterOwner};Theme.Window(w,dark);var root=new DockPanel{Margin=new Thickness(20)};var note=Theme.Text("点击诊断跳转到代码；英文原文完整保留。",12);DockPanel.SetDock(note,Dock.Top);root.Children.Add(note);var rows=new StackPanel{Margin=new Thickness(0,14,0,0)};foreach(var item in locations){var location=item;var b=dark?Dark.Button(""):Theme.Button("");b.HorizontalContentAlignment=HorizontalAlignment.Left;b.Content=Theme.Text(item.Raw+"\n"+global::Diagnostics.Translate(item.Raw),12);b.Margin=new Thickness(0,0,0,8);b.Click+=(s,e)=>{CloseThen(w,()=>jump(location.Line,location.Column));};rows.Children.Add(b);}root.Children.Add(new ScrollViewer{Content=rows,VerticalScrollBarVisibility=ScrollBarVisibility.Auto});w.Content=root;w.ShowDialog();}
}

sealed class Difference {
 public int ExpectedOffset,ActualOffset,ExpectedLength,ActualLength,Token;public bool Equal;
 public static Difference Find(string expected,string actual,bool strict=false){string why;var d=new Difference{Equal=Engine.Match(expected,actual,out why,strict)};if(d.Equal)return d;var a=Regex.Matches(expected,@"\S+");var b=Regex.Matches(actual,@"\S+");for(int i=0;i<Math.Max(a.Count,b.Count);i++){bool equal=false;if(i<a.Count&&i<b.Count)equal=Engine.Match(a[i].Value,b[i].Value,out why,strict);if(equal)continue;d.Token=i+1;d.ExpectedOffset=i<a.Count?a[i].Index:expected.Length;d.ActualOffset=i<b.Count?b[i].Index:actual.Length;d.ExpectedLength=i<a.Count?a[i].Length:0;d.ActualLength=i<b.Count?b[i].Length:0;break;}return d;}
}

sealed class ComparisonWindow : Window {
 Evaluation ev;ComboBox cases;RichTextBox wanted,actual;TextBox input;TextBlock diagnosis;CheckBox whitespace,failed;
 public ComparisonWindow(Evaluation evaluation,bool dark=false){ev=evaluation;Title="失败用例对比";Width=1020;Height=720;MinWidth=720;MinHeight=500;WindowStartupLocation=WindowStartupLocation.CenterOwner;Theme.Window(this,dark);var root=new Grid{Margin=new Thickness(20)};root.RowDefinitions.Add(new RowDefinition{Height=GridLength.Auto});root.RowDefinitions.Add(new RowDefinition{Height=new GridLength(100)});root.RowDefinitions.Add(new RowDefinition{Height=GridLength.Auto});root.RowDefinitions.Add(new RowDefinition{Height=new GridLength(1,GridUnitType.Star)});root.RowDefinitions.Add(new RowDefinition{Height=GridLength.Auto});Content=root;
 var bar=new DockPanel();failed=new CheckBox{Content="只看失败用例",IsChecked=true,Margin=new Thickness(12,0,12,0),VerticalAlignment=VerticalAlignment.Center};whitespace=new CheckBox{Content="显示空格与换行",Margin=new Thickness(0,0,0,0),VerticalAlignment=VerticalAlignment.Center};DockPanel.SetDock(whitespace,Dock.Right);DockPanel.SetDock(failed,Dock.Right);bar.Children.Add(whitespace);bar.Children.Add(failed);cases=new ComboBox{MinWidth=200};if(dark)Dark.StyleCombo(cases);else Dark.StyleLightCombo(cases);bar.Children.Add(cases);root.Children.Add(bar);
 input=Read();input.Margin=new Thickness(0,12,0,10);L.Exclude(input);Grid.SetRow(input,1);root.Children.Add(input);diagnosis=Theme.Text("",12);diagnosis.Margin=new Thickness(0,0,0,10);Grid.SetRow(diagnosis,2);root.Children.Add(diagnosis);
 var panes=new Grid();panes.ColumnDefinitions.Add(new ColumnDefinition{Width=new GridLength(1,GridUnitType.Star)});panes.ColumnDefinitions.Add(new ColumnDefinition{Width=new GridLength(12)});panes.ColumnDefinitions.Add(new ColumnDefinition{Width=new GridLength(1,GridUnitType.Star)});wanted=Output();actual=Output();for(int i=0;i<2;i++){var p=new DockPanel();var label=Theme.Text(i==0?"预期输出":"实际输出",13,Theme.Blue,true);label.Margin=new Thickness(0,0,0,10);DockPanel.SetDock(label,Dock.Top);p.Children.Add(label);p.Children.Add(i==0?wanted:actual);Grid.SetColumn(p,i*2);panes.Children.Add(p);}Grid.SetRow(panes,3);root.Children.Add(panes);var footer=Theme.Text("红色标出首个不一致的输出项；判题忽略空白差异，浮点容差为 0.0001。",11,Theme.Muted);footer.Margin=new Thickness(0,12,0,0);Grid.SetRow(footer,4);root.Children.Add(footer);failed.Checked+=(s,e)=>Populate();failed.Unchecked+=(s,e)=>Populate();whitespace.Checked+=(s,e)=>ShowCase();whitespace.Unchecked+=(s,e)=>ShowCase();cases.SelectionChanged+=(s,e)=>ShowCase();Populate();}
 static TextBox Read(){return new TextBox{IsReadOnly=true,AcceptsReturn=true,TextWrapping=TextWrapping.NoWrap,VerticalScrollBarVisibility=ScrollBarVisibility.Auto,HorizontalScrollBarVisibility=ScrollBarVisibility.Auto,Background=Theme.White,Foreground=Theme.Ink,BorderBrush=Theme.Line,Padding=new Thickness(10),FontFamily=new FontFamily("Consolas, Microsoft YaHei UI"),FontSize=13};}
 static RichTextBox Output(){var b=new RichTextBox{IsReadOnly=true,VerticalScrollBarVisibility=ScrollBarVisibility.Auto,HorizontalScrollBarVisibility=ScrollBarVisibility.Auto,Background=Theme.White,Foreground=Theme.Ink,BorderBrush=Theme.Line,FontFamily=new FontFamily("Consolas, Microsoft YaHei UI"),FontSize=14};L.Exclude(b);return b;}
 void Populate(){cases.Items.Clear();for(int i=0;i<ev.Cases.Count;i++){var c=ev.Cases[i];if(failed.IsChecked==true&&c.Passed)continue;cases.Items.Add(new ComboBoxItem{Content="用例 "+(i+1)+" · "+(c.Passed?"通过":"失败"),Tag=c});}if(cases.Items.Count>0)cases.SelectedIndex=0;else{input.Text="";wanted.Document.Blocks.Clear();actual.Document.Blocks.Clear();diagnosis.Text=ev.Compiled?"当前没有失败用例。":"编译失败，未生成测试输出。请使用错误定位查看诊断。";}}
 void ShowCase(){var item=cases.SelectedItem as ComboBoxItem;if(item==null)return;var c=(CaseResult)item.Tag;input.Text=c.Test.Input;bool strict=ev.ProblemId==38||ev.ProblemId==52||ev.ProblemId==56||ev.ProblemId==58||ev.ProblemId==122||ev.ProblemId==123||ev.ProblemId==124;var diff=Difference.Find(c.Test.Expected,c.Run.Output,strict);diagnosis.Text=L.Diagnosis(c.Diagnosis)+"\n"+(diff.Equal?"输出按判题规则一致。":"首个不同输出项："+diff.Token)+" · "+c.Run.Millis.ToString("0.0")+" ms · Exit "+c.Run.ExitCode;Paint(wanted,c.Test.Expected,diff.ExpectedOffset,diff.ExpectedLength,!diff.Equal);Paint(actual,c.Run.Output,diff.ActualOffset,diff.ActualLength,!diff.Equal);}
 string Visible(string s){return whitespace.IsChecked==true?s.Replace(" ","·").Replace("\t","⇥").Replace("\r","").Replace("\n","↵\n"):s;}
 void Paint(RichTextBox box,string text,int start,int length,bool mark){box.Document.Blocks.Clear();var p=new Paragraph{Margin=new Thickness(0)};if(!mark)p.Inlines.Add(new Run(Visible(text)));else{p.Inlines.Add(new Run(Visible(text.Substring(0,start))));p.Inlines.Add(new Run(length==0?"∅":Visible(text.Substring(start,length))){Background=Theme.B("#FFDFDF"),Foreground=Theme.B("#942D42"),FontWeight=FontWeights.Bold});p.Inlines.Add(new Run(Visible(text.Substring(start+length))));}box.Document.Blocks.Add(p);}
}

sealed class CustomExecution {public bool Compiled;public string Compiler;public Execution Run;}
static class CustomRunner {
 public static CustomExecution Run(string code,string input,CancellationToken token){if(Encoding.UTF8.GetByteCount(input)>65536)throw new ArgumentException("输入不能超过 64 KiB。");Engine.EnsureCompiler();string dir=Path.Combine(Engine.DataRoot,"runs","custom-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(dir);try{string src=Path.Combine(dir,"answer.c"),exe=Path.Combine(dir,"answer.exe");File.WriteAllText(src,code,new UTF8Encoding(false));var compile=Engine.Execute(Engine.CompilerPath,"-B\""+Path.GetDirectoryName(Engine.CompilerPath)+"\" -Wall \""+src+"\" -o \""+exe+"\"","",15000,token,dir);token.ThrowIfCancellationRequested();var result=new CustomExecution{Compiler=(compile.Failure+"\n"+compile.Error+compile.Output).Replace(src,"answer.c"),Compiled=compile.Failure==""&&compile.ExitCode==0&&File.Exists(exe)};if(result.Compiled){result.Run=Engine.Execute(exe,"",input,3000,token,dir);token.ThrowIfCancellationRequested();}return result;}finally{try{Directory.Delete(dir,true);}catch{}}}
}
sealed class CustomRunWindow : Window {
 string code;TextBox input,output;Button run,stop,errors;TextBlock state;CancellationTokenSource cancel;bool busy;CustomExecution result;Action<int,int> jump;
 public CustomRunWindow(string source,string savedInput,Action<string> saveInput,Action<int,int> jumpTo,bool dark=false){code=source;jump=jumpTo;Title="自定义输入试跑";Width=850;Height=670;MinWidth=620;MinHeight=480;WindowStartupLocation=WindowStartupLocation.CenterOwner;Theme.Window(this,dark);var root=new Grid{Margin=new Thickness(20)};foreach(var h in new[]{GridLength.Auto,new GridLength(.8,GridUnitType.Star),GridLength.Auto,new GridLength(1,GridUnitType.Star),GridLength.Auto})root.RowDefinitions.Add(new RowDefinition{Height=h});Content=root;root.Children.Add(Theme.Text("使用当前代码快照试跑；不计分、不解锁关卡。每次运行限制 3 秒 / 256 MiB。",12));input=new TextBox{Text=savedInput??"",AcceptsReturn=true,AcceptsTab=true,VerticalContentAlignment=VerticalAlignment.Top,FontFamily=new FontFamily("Consolas"),FontSize=14,VerticalScrollBarVisibility=ScrollBarVisibility.Auto,HorizontalScrollBarVisibility=ScrollBarVisibility.Auto,Padding=new Thickness(12),Background=Theme.White,BorderBrush=Theme.Line,Margin=new Thickness(0,12,0,12),MaxLength=65536};L.Exclude(input);Grid.SetRow(input,1);root.Children.Add(input);
 var bar=new DockPanel();var tools=new StackPanel{Orientation=Orientation.Horizontal};run=dark?Dark.Button("运行输入"):Theme.Button("运行输入",true);stop=dark?Dark.Button("停止"):Theme.Button("停止");stop.IsEnabled=false;errors=PracticeTools.Icon("错误定位",PracticeTools.Target,()=>{if(result!=null)PracticeTools.Diagnostics(this,result.Compiler,(line,col)=>{PracticeTools.CloseThen(this,()=>jump(line,col));},dark);},dark);errors.IsEnabled=false;tools.Children.Add(run);tools.Children.Add(stop);tools.Children.Add(errors);DockPanel.SetDock(tools,Dock.Right);bar.Children.Add(tools);bar.Children.Add(Theme.Text("标准输入 → 程序输出",13,Theme.Blue,true));Grid.SetRow(bar,2);root.Children.Add(bar);output=new TextBox{IsReadOnly=true,AcceptsReturn=true,TextWrapping=TextWrapping.NoWrap,FontFamily=new FontFamily("Consolas, Microsoft YaHei UI"),FontSize=13,Background=Theme.White,Foreground=Theme.Ink,BorderBrush=Theme.Line,Padding=new Thickness(12),Margin=new Thickness(0,12,0,12),VerticalContentAlignment=VerticalAlignment.Top,VerticalScrollBarVisibility=ScrollBarVisibility.Auto,HorizontalScrollBarVisibility=ScrollBarVisibility.Auto};L.Exclude(output);Grid.SetRow(output,3);root.Children.Add(output);state=Theme.Text("输入测试数据后点击运行。",11,Theme.Muted);Grid.SetRow(state,4);root.Children.Add(state);run.Click+=async(s,e)=>await Execute();stop.Click+=(s,e)=>{if(cancel!=null)cancel.Cancel();};Closing+=(s,e)=>{if(busy){cancel.Cancel();e.Cancel=true;state.Text="正在停止运行，请稍后再关闭窗口";}};Closed+=(s,e)=>{if(saveInput!=null)saveInput(input.Text);};}
 public async Task Execute(){if(busy)return;busy=true;run.IsEnabled=input.IsEnabled=false;stop.IsEnabled=true;errors.IsEnabled=false;state.Text="正在编译和运行…";string data=input.Text;cancel=new CancellationTokenSource();try{result=await Task.Run(()=>CustomRunner.Run(code,data,cancel.Token));errors.IsEnabled=ErrorLocation.Parse(result.Compiler).Count>0;output.Text=result.Compiled?result.Run.Output:L.T("编译失败")+"\n"+Diagnostics.Explain(result.Compiler);state.Text=!result.Compiled?"编译失败":result.Run.Failure!=""?result.Run.Failure:"运行完成 · "+result.Run.Millis.ToString("0.0")+" ms · Exit "+result.Run.ExitCode;if(result.Compiled&&!string.IsNullOrEmpty(result.Run.Error))output.Text+="\n\n[stderr]\n"+result.Run.Error;}catch(OperationCanceledException){state.Text="已停止";}catch(Exception ex){state.Text=ex.Message;}finally{busy=false;run.IsEnabled=input.IsEnabled=true;stop.IsEnabled=false;cancel.Dispose();cancel=null;}}
}
